<div class="dashboard-welcome"><div><h2>Your newsroom, at a glance.</h2><p>Publish stories, manage your content and keep your community informed.</p></div><span><?= e(date('d')) ?><small><?= e(strtoupper(date('M Y'))) ?></small></span></div><div class="stat-grid"><?php foreach ($stats as $label=>$value): ?><div class="stat"><span><?= e($label) ?></span><strong><?= number_format((int)$value) ?></strong></div><?php endforeach ?></div><section class="panel"><div class="section-heading"><h2>Recent stories</h2><a class="text-link" href="<?= e(url('admin/articles')) ?>">View all →</a></div><?php if (!$recent): ?><p class="muted">Your newsroom is ready. Write your first story to get started.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Story</th><th>Status</th><th>Views</th><th>Updated</th></tr></thead><tbody><?php foreach ($recent as $row): ?><tr><td><a href="<?= e(url('admin/articles/edit/'.$row['id'])) ?>"><?= e($row['title_en'] ?: ($row['title_si'] ?: $row['title_ta'])) ?></a></td><td><span class="status <?= e($row['status']) ?>"><?= e($row['status']) ?></span></td><td><?= number_format($row['views']) ?></td><td><?= e($row['updated_at']) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section><div class="quick-grid"><a href="<?= e(url('admin/media')) ?>" class="panel"><span class="eyebrow">MEDIA LIBRARY</span><h2>Give stories a new dimension ↗</h2><p>Upload images, video and supporting documents.</p></a><?php if ($user['role']!=='reporter'): ?><a href="<?= e(url('admin/classifieds')) ?>" class="panel"><span class="eyebrow">COMMUNITY</span><h2>Review the community board ↗</h2><p>Review classified listings before they reach your readers.</p></a><a href="<?= e(url('admin/advertisements')) ?>" class="panel"><span class="eyebrow">AD PUBLISHING</span><h2>Manage your campaigns ↗</h2><p>Publish image, video and sponsored ads across the website.</p></a><?php endif ?></div>
